<script setup lang="ts">
import {ref} from 'vue'
import {useToast} from 'primevue/usetoast'
import {useTicketService} from '@/services/ticket.service'
import type {TicketDocument} from '@/types'
const props=defineProps<{ticketId:string;documents:TicketDocument[]}>(),emit=defineEmits<{(e:'uploaded'):void}>(),toast=useToast()
const {uploadDocument,getDownloadUrl}=useTicketService(),uploading=ref(false)
async function onFileChange(event:Event){const target=event.target as HTMLInputElement;if(!target.files?.length)return;const file=target.files[0];if(file.size>10*1024*1024){toast.add({severity:'warn',summary:'Archivo demasiado grande',detail:'El archivo no puede superar los 10 MB.',life:4000});target.value='';return}const data=new FormData();data.append('file',file);uploading.value=true;try{await uploadDocument(props.ticketId,data);emit('uploaded');toast.add({severity:'success',summary:'Documento cargado',life:3000})}catch(error){toast.add({severity:'error',summary:'No se pudo cargar el documento',detail:error instanceof Error?error.message:'Inténtalo de nuevo.',life:4500})}finally{uploading.value=false;target.value=''}}
async function download(doc:TicketDocument){try{const {downloadUrl}=await getDownloadUrl(doc.fileKey);window.open(downloadUrl,'_blank','noopener')}catch(error){toast.add({severity:'error',summary:'No se pudo descargar el documento',detail:error instanceof Error?error.message:'Inténtalo de nuevo.',life:4500})}}
function formatSize(bytes:number){if(bytes<1024)return bytes+' B';if(bytes<1024*1024)return(bytes/1024).toFixed(1)+' KB';return(bytes/(1024*1024)).toFixed(1)+' MB'}
</script>
<template><div class="document-upload"><div class="flex flex-column gap-sm"><div class="flex flex-wrap gap-md" style="align-items:center"><label for="fileInput" class="document-upload-trigger"><i class="fa-solid fa-arrow-up-from-bracket" aria-hidden="true"></i>Subir documento</label><input id="fileInput" class="visually-hidden-input" type="file" accept=".pdf,.jpg,.png,.doc,.docx" :disabled="uploading" @change="onFileChange"/><span class="text-small text-muted">PDF, JPG, PNG o DOC · Máximo 10 MB</span></div>
<div v-if="uploading" class="flex-center gap-sm" role="status"><ProgressSpinner/><span class="text-small">Subiendo documento…</span></div><div v-if="documents.length" class="documents-list mt-sm flex flex-column gap-sm"><div v-for="doc in documents" :key="doc.id" class="document-item"><i class="fa-regular fa-file-lines" style="color:var(--primary)" aria-hidden="true"></i><span class="document-name">{{doc.originalName}}</span><span class="text-small text-muted">{{formatSize(doc.fileSize||0)}}</span><Button icon="fa-solid fa-download" text rounded aria-label="Descargar documento" title="Descargar documento" @click="download(doc)"/></div></div><p v-else class="text-small text-muted mt-sm">Todavía no hay documentos adjuntos.</p></div></div></template>
